    --ag2-win-y: calc((100vh - var(--ag2-win-h)) / 2);
    --ag2-set-nav: 252px;
    --ag2-set-head: 86px;
}

html body.ag2:not(#_):not(#__) :is(#ag2-set-dim, #ag2-settings)[hidden] {
