/* == 5.5c · Anchor capsules · cross-page search · hit flash == */
/* Long pages (连接, 生成参数, 提示词与格式) get a row of anchor capsules in the window head,
   under the lead line; the head grows by --ag2-set-anchors so the drawer box (positioned
   from --ag2-set-head) starts below it. Sticky by construction: it is outside the scroller. */
html body.ag2[data-ag2-anchors]:not(#_):not(#__) {
    --ag2-set-head: 124px;
}

html body.ag2:not(#_):not(#__) #ag2-settings .ag2-set-head {
    flex-wrap: wrap;
    align-content: flex-start;
}

html body.ag2:not(#_):not(#__) #ag2-settings .ag2-anchors {
    display: flex;
    flex: 0 0 100%;
    gap: 6px;
    order: 3;
    min-width: 0;
    margin: 4px 0 0;
    padding: 0 12px 6px 0;
    overflow-x: auto;
    overflow-y: hidden;
    scrollbar-width: none;
}

html body.ag2:not(#_):not(#__) #ag2-settings .ag2-anchors::-webkit-scrollbar {
    display: none;
}

html body.ag2:not(#_):not(#__) #ag2-settings .ag2-anchors[hidden] {
    display: none;
}

html body.ag2:not(#_):not(#__) #ag2-settings .ag2-anchor {
    flex: none;
    height: 26px;
    margin: 0;
    padding: 0 11px;
    border: 0;
    border-radius: 13px;
    background: var(--ag2-f4);
    color: var(--ag2-l2);
    font: inherit;
    font-size: 12.5px;
    font-weight: 560;
    white-space: nowrap;
    cursor: pointer;
    transition: background-color var(--ag2-dur) ease, color var(--ag2-dur) ease;
}

html body.ag2:not(#_):not(#__) #ag2-settings .ag2-anchor:hover {
    background: var(--ag2-f3);
    color: var(--ag2-l1);
}

html body.ag2:not(#_):not(#__) #ag2-settings .ag2-anchor[aria-current="true"] {
    background: var(--ag2-accent-soft);
    color: var(--ag2-accent-hover);
}

html body.ag2:not(#_):not(#__) #ag2-settings .ag2-anchor:focus-visible {
    outline: 2px solid var(--ag2-accent);
    outline-offset: 1px;
}

/* search results replace the nav tiles while the field has text */
html body.ag2:not(#_):not(#__) #ag2-settings.ag2-searching .ag2-set-grp {
    display: none;
}

html body.ag2:not(#_):not(#__) #ag2-settings .ag2-set-results {
