}

html body.ag2:not(#_):not(#__) #ag2-settings .ag2-res:hover,
html body.ag2:not(#_):not(#__) #ag2-settings .ag2-res.ag2-sel {
    background: var(--ag2-f4);
}

html body.ag2:not(#_):not(#__) #ag2-settings .ag2-res:focus-visible {
    outline: 2px solid var(--ag2-accent);
    outline-offset: -2px;
}

html body.ag2:not(#_):not(#__) #ag2-settings .ag2-res-txt {
