    font-weight: 520;
}

html body.ag2:not(#_):not(#__) #ag2-settings .ag2-res-item mark {
    background: none;
    color: inherit;
    font-weight: 700;
    text-decoration: underline;
    text-underline-offset: 2px;
}

html body.ag2:not(#_):not(#__) #ag2-settings .ag2-res-path {
    color: var(--ag2-l3);
    font-size: 11.5px;
}

html body.ag2:not(#_):not(#__) #ag2-settings .ag2-res-empty {
    padding: 14px 8px;
    color: var(--ag2-l3);
    font-size: 12.5px;
    text-align: center;
}

/* hit: accent ring + soft fill, blinks for 1.2s; reduced motion → static ring only.
   Explicit here: the §14 media-query catch-all is less specific than this rule, so it
   would not shorten the blink under the system setting. */
/* the ring is an inset outline, not box-shadow: buttons / fields set their own box-shadow
   with !important (添加背景 showed no ring at all). No !important on outline here — an
   !important value would also beat the keyframes and stop the blink; an extra id-level
   :not() outranks ST's own outline rules instead. */
html body.ag2:not(#_):not(#__):not(#___) .ag2-hit {
    border-radius: 8px;
    outline: 2px solid var(--ag2-accent);
    outline-offset: -2px;
    animation: ag2-hit 1.2s ease-in-out both !important;
}

html body.ag2.reduced-motion:not(#_):not(#__):not(#___) .ag2-hit {
    animation: none !important;
}

@media (prefers-reduced-motion: reduce) {
    html body.ag2:not(#_):not(#__):not(#___) .ag2-hit {
        animation: none !important;
    }
}

@keyframes ag2-hit {
    0%, 50%, 100% { outline-color: var(--ag2-accent); background-color: var(--ag2-accent-soft); }
    25%, 75% { outline-color: transparent; background-color: transparent; }
}

/* == 5.5d · 通用: items with no effect under the AG2 layout (greyed + note) == */
/* 页面宽度 (chat_width: AG2 sizes the reading column from 外观 › 行宽) and 可移动 UI
   (the shell places every panel itself). ST keeps the values; other themes still use them. */
@media screen { /* desktop + phone since P5 (§5.9 overrides the geometry) */
    html body.ag2.ag2-set-open:not(#_):not(#__) #user-settings-block :is(div:has(> #chat_width_slider), div:has(> #movingUIModeCheckBlock), #MovingUI-presets-block) {
