        content: "新布局下无效：聊天宽度请在“外观 › 行宽”中调整";
        text-align: center;
    }

    html body.ag2.ag2-set-open:not(#_):not(#__) #user-settings-block div:has(> #movingUIModeCheckBlock) {
        flex-wrap: wrap;
    }

    html body.ag2.ag2-set-open:not(#_):not(#__) #user-settings-block div:has(> #movingUIModeCheckBlock)::after {
