    html body.ag2.ag2-insp-open:not(#_):not(#__) #right-nav-panel[data-ag2-insp="char"] #firstMessageWrapper { order: 2; }
    html body.ag2 #right-nav-panel .ag2-insp-links { order: 3; }
    html body.ag2.ag2-insp-open:not(#_):not(#__) #right-nav-panel[data-ag2-insp="char"] #spoiler_free_desc { order: 4; }
    html body.ag2 #right-nav-panel .ag2-insp-foot { order: 5; }

    html body.ag2 #right-nav-panel .ag2-insp-card-head {
        display: flex;
        align-items: center;
