        color: var(--ag2-l3);
        font-size: 12.5px;
        font-weight: 640;
    }

    html body.ag2 #right-nav-panel .ag2-insp-link {
        color: var(--ag2-accent);
        font-size: 12.5px;
        font-weight: 640;
        white-space: nowrap;
    }

    html body.ag2 #right-nav-panel .ag2-insp-link:hover {
        color: var(--ag2-accent-hover);
    }

    /* 3-line summary (description), 2 lines (first message) */
    html body.ag2 #right-nav-panel .ag2-insp-sum {
        display: -webkit-box;
        -webkit-box-orient: vertical;
        -webkit-line-clamp: 3;
        overflow: hidden;
        color: var(--ag2-l1);
