    }

    /* “编辑”: ST's own textarea opens in place of the summary */
    html body.ag2.ag2-insp-open:not(#_):not(#__) #right-nav-panel[data-ag2-insp="char"] :is(#description_textarea, #firstmessage_textarea) {
        display: none !important;
    }

    html body.ag2.ag2-insp-open:not(#_):not(#__) #right-nav-panel[data-ag2-insp="char"][data-ag2-edit="desc"] #description_textarea,
    html body.ag2.ag2-insp-open:not(#_):not(#__) #right-nav-panel[data-ag2-insp="char"][data-ag2-edit="first"] #firstmessage_textarea {
