        padding: 9px 11px !important;
        border: 0 !important;
        border-radius: 10px !important;
        background: rgba(0, 0, 0, 0.28) !important;
        box-shadow: inset 0 0 0 0.5px var(--ag2-sep-strong) !important;
        color: var(--ag2-l1) !important;
        font-size: var(--ag2-fs-sub) !important;
        line-height: 1.55 !important;
        resize: vertical;
        field-sizing: fixed;
    }

    html body.ag2 #right-nav-panel[data-ag2-edit="desc"] #ag2-insp-desc-sum,
    html body.ag2 #right-nav-panel[data-ag2-edit="first"] #ag2-insp-first-sum {
        display: none;
    }

    /* creator's notes: ST's own block, shown on request from the entry list */
    html body.ag2.ag2-insp-open:not(#_):not(#__) #right-nav-panel[data-ag2-insp="char"] #spoiler_free_desc {
        display: none !important;
    }

    html body.ag2.ag2-insp-open:not(#_):not(#__) #right-nav-panel[data-ag2-insp="char"][data-ag2-notes] #spoiler_free_desc {
