    }

    /* secondary entries: one grouped list */
    html body.ag2 #right-nav-panel .ag2-insp-links,
    html body.ag2 #right-nav-panel .ag2-insp-card {
        flex: none;
        display: flex;
        flex-direction: column;
        padding: 4px 0;
        border-radius: var(--ag2-r-card);
        background: var(--ag2-f3);
    }

    html body.ag2 #right-nav-panel .ag2-insp-row,
    html body.ag2 #right-nav-panel .ag2-insp-kv {
        display: flex;
        align-items: center;
        gap: 10px;
        min-height: 40px;
