        color: var(--ag2-l1);
        font-size: var(--ag2-fs-sub);
    }

    html body.ag2 #right-nav-panel :is(.ag2-insp-row-v, .ag2-insp-v) {
        flex: 1;
        min-width: 0;
        overflow: hidden;
        color: var(--ag2-l3);
        font-size: 12.5px;
        text-align: right;
        white-space: nowrap;
        text-overflow: ellipsis;
    }

    html body.ag2 #right-nav-panel .ag2-insp-chev {
        color: var(--ag2-l4);
    }

    html body.ag2 #right-nav-panel .ag2-insp-foot {
        display: flex;
        justify-content: space-between;
        gap: 10px;
        padding: 2px 6px 4px;
        color: var(--ag2-l3);
        font-size: 11.5px;
        font-variant-numeric: tabular-nums;
    }

    /* --- 本次对话 page --- */
    html body.ag2 #right-nav-panel .ag2-insp-chat {
        flex: 1 1 auto;
        min-height: 0;
        display: flex;
        flex-direction: column;
        gap: 10px;
        padding: 0 12px 14px;
        overflow-y: auto;
    }

    html body.ag2 #right-nav-panel .ag2-insp-v {
        color: var(--ag2-l2);
        white-space: normal;
        overflow-wrap: anywhere;
        padding: 9px 0;
    }

    html body.ag2 #right-nav-panel .ag2-insp-hint {
        margin: 2px 6px;
        color: var(--ag2-l3);
        font-size: var(--ag2-fs-foot);
        line-height: 1.5;
    }

    /* ST's floating panels (作者注释 / CFG / Logprobs) keep their own nodes and
       behaviour; only placed: left of the open inspector, else under the tool capsule
       (§5.6). ST may have written a saved MovingUI position inline, hence !important. */
    html body.ag2:not(#_):not(#__) :is(#floatingPrompt, #cfgConfig, #logprobsViewer) {
        position: fixed !important;
        top: calc(var(--ag2-inset) + 54px) !important;
        right: var(--ag2-inset) !important;
        left: auto !important;
        bottom: auto !important;
        width: var(--ag2-insp-w) !important;
        min-width: 0 !important;
        max-width: calc(100vw - var(--ag2-sheld-left) - var(--ag2-inset) * 2) !important;
        height: auto !important;
        max-height: calc(100dvh - var(--ag2-inset) * 2 - 54px) !important;
        margin: 0 !important;
        border: 0 !important;
        border-radius: var(--ag2-r-panel) !important;
        background: var(--ag2-mat-menu) !important;
        -webkit-backdrop-filter: var(--ag2-blur-menu) !important;
        backdrop-filter: var(--ag2-blur-menu) !important;
        box-shadow: var(--ag2-rim), var(--ag2-sh3) !important;
    }

    html body.ag2.ag2-insp-open:not(#_):not(#__) :is(#floatingPrompt, #cfgConfig, #logprobsViewer) {
        top: var(--ag2-inset) !important;
        right: calc(var(--ag2-inset) * 2 + var(--ag2-insp-w)) !important;
        max-height: calc(100dvh - var(--ag2-inset) * 2) !important;
    }

    /* menus anchored in the inspector: above ST's z-3005 layer, below its popups (4000+) */
    html body.ag2 #ag2-layer {
        position: fixed;
        inset: 0;
        z-index: 3006;
        pointer-events: none;
        color: var(--ag2-l1);
        font-size: var(--ag2-fs-body);
    }

    html body.ag2 #ag2-layer > * {
        pointer-events: auto;
    }
}

/* == 5.6b · Inspector: group page (#rm_group_chats_block, ST's nodes re-laid out) == */
/* Each of ST's three inline drawers (群聊控制 / 当前成员 / 添加成员) becomes a card;
   inside, the avatar + action buttons lead, the strategy selects follow as a 2-column
   grid, members are compact rows. Display of individual controls is never forced: ST
   toggles some (join prefix/suffix, restore avatar, submit) with inline display. */
@media screen { /* desktop + phone since P5 (§5.9 overrides the geometry) */
    html body.ag2.ag2-insp-open:not(#_):not(#__) #right-nav-panel #rm_group_chats_block {
        color: var(--ag2-l1);
        font-size: var(--ag2-fs-sub);
