    /* list page (or nothing open): the chat stays laid out but leaves the a11y tree and
       the blur count once the list has slid over it */
    html body.ag2.ag2-phone:is(:not([data-ag2-ph="chat"]), .ag2-welcome):not(#_):not(#__) #sheld {
        visibility: hidden !important;
        transition: visibility 0s linear var(--ag2-dur-panel);
    }

    html body.ag2.ag2-phone:not(#_):not(#__) #chat {
        padding-top: calc(var(--ag2-safe-t) + 62px) !important;
