        padding-left: max(14px, var(--ag2-safe-l), calc((100% - var(--ag2-read-width)) / 2)) !important;
        padding-right: max(14px, var(--ag2-safe-r), calc((100% - var(--ag2-read-width)) / 2)) !important;
        padding-bottom: calc(var(--ag2-dock-h, 112px) + 12px) !important;
        border: 0 !important;
    }

    /* meta line: on a 360px column the model name shrinks (ellipsis) instead of pushing
       the meta over the action buttons (小白X adds one there) */
    html body.ag2.ag2-phone:not(#_):not(#__) #chat .mes {
        grid-template-columns:
            [outer] var(--ag2-mes-ol) [card] var(--ag2-mes-pl)
