    }

    html body.ag2.ag2-phone:not(#_):not(#__) #chat .mes .mes_buttons > * {
        flex-shrink: 0;
    }

    /* menus: 44px rows on touch (§5.9) */
    html body.ag2.ag2-phone:not(#_):not(#__) :is(#ag2-shell, #ag2-layer) .ag2-menu-item {
