        background: var(--ag2-mat-window) !important;
        -webkit-backdrop-filter: var(--ag2-blur-window) !important;
        backdrop-filter: var(--ag2-blur-window) !important;
        box-shadow: var(--ag2-rim), var(--ag2-sh3) !important;
        animation: ag2-sheet-up var(--ag2-dur-panel) var(--ag2-ease-sheet);
