        position: relative;
        z-index: 1;
        display: inline-flex;
        align-items: center;
        gap: 0;
        height: 44px;
        padding: 0 10px 0 2px;
        border: 0;
        background: none;
        color: var(--ag2-accent);
        font-size: 17px;
        font-weight: 500;
    }

    html body.ag2.ag2-phone:not(#_):not(#__) #ag2-settings.ag2-set-phone .ag2-set-titles {
        position: absolute;
        inset: 0 96px;
        display: flex;
        align-items: center;
        justify-content: center;
        pointer-events: none;
    }

    html body.ag2.ag2-phone:not(#_):not(#__) #ag2-settings.ag2-set-phone .ag2-set-head h1 {
        overflow: hidden;
        font-size: 17px;
        font-weight: 650;
        line-height: 22px;
        text-overflow: ellipsis;
        white-space: nowrap;
    }

    html body.ag2.ag2-phone:not(#_):not(#__) #ag2-settings.ag2-set-phone :is(.ag2-set-lead, .ag2-set-close, .ag2-anchors) {
        display: none !important;
    }

    html body.ag2.ag2-phone:not(#_):not(#__) #ag2-settings.ag2-set-phone .ag2-set-body {
        padding: 0 16px calc(24px + var(--ag2-safe-b));
    }

    /* the open ST drawer fills the sheet under the head (rule 1: CSS only) */
    html body.ag2.ag2-phone.ag2-set-open:not(#_):not(#__) :is(#rm_api_block, #left-nav-panel, #AdvancedFormatting, #WorldInfo, #PersonaManagement, #Backgrounds, #user-settings-block, #rm_extensions_block).openDrawer {
        padding: 0 calc(16px + var(--ag2-safe-r)) calc(24px + var(--ag2-safe-b)) calc(16px + var(--ag2-safe-l)) !important;
        border-radius: 0 !important;
    }

    html body.ag2.ag2-phone.ag2-set-open:not(#_):not(#__) #left-nav-panel.openDrawer {
        padding-right: 0 !important;
    }

    html body.ag2.ag2-phone.ag2-set-open:not(#_):not(#__) #left-nav-panel.openDrawer > .scrollableInner {
        padding: 0 calc(16px + var(--ag2-safe-r)) calc(24px + var(--ag2-safe-b)) 0 !important;
    }

    /* 扩展: ST's head row (title · notify · manage · install) wraps instead of squeezing the
       title into a one-character column */
    html body.ag2.ag2-phone.ag2-set-open:not(#_):not(#__) #rm_extensions_block .extensions_block > .flex-container:first-child {
        flex-wrap: wrap;
    }

    html body.ag2.ag2-phone.ag2-set-open:not(#_):not(#__) #rm_extensions_block .extensions_block > .flex-container:first-child > h3 {
        flex: 1 0 100%;
    }

    /* --- command palette: top sheet, clear of the notch and the keyboard --- */
    html body.ag2.ag2-phone:not(#_):not(#__) #ag2-palette {
        inset: calc(var(--ag2-safe-t) + var(--ag2-vvt, 0px) + 8px) 0 auto 0;
        width: calc(100vw - 16px);
        max-height: calc(var(--ag2-ph-h) - var(--ag2-safe-t) - 16px);
    }

    html body.ag2.ag2-phone:not(#_):not(#__) #ag2-palette .ag2-pal-input {
        font-size: 17px;
    }

    html body.ag2.ag2-phone:not(#_):not(#__) #ag2-palette .ag2-pal-row {
        min-height: 48px;
    }

    html body.ag2.ag2-phone:not(#_):not(#__) #ag2-palette :is(.ag2-pal-foot, .ag2-pal-enter, kbd) {
        display: none;
    }
}

/* phone-only shell nodes never show on the desktop layout (and the reverse) */
html body.ag2:not(.ag2-phone):not(#_):not(#__) .ag2-ph-x,
html body.ag2:not(#_):not(#__) #ag2-settings:not(.ag2-set-phone) :is(.ag2-set-grab, .ag2-set-phead, .ag2-set-me, .ag2-set-back) {
    display: none !important;
}

@media (min-width: 1001px) {
    html body.ag2:not(#_):not(#__) .ag2-ph-x {
        display: none !important;
    }
}

/* == 13 · Ported fixes (apple-theme.css §15m, §19b, §17a) == */
/* Under AG2 ST's own panels still render with the theme JSON's blur strength and
   none of AG Dark's fixes; these two keep the §4.6 regression at zero until the
   P2 settings window restyles the panels. */

/* §7 / §18a: a blurred panel never contains another blurred layer (ST gives the
   formatting notice, background tabs and tile toggles their own blur). */
html body.ag2:not(#_):not(#__) .drawer-content *,
html body.ag2:not(#_):not(#__) .bg_example .mobile-only-menu-toggle {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}

/* §19b: text buttons keep their label on one line (“重置”, Extras “连接” were
   squeezed into one-glyph-per-line pills). :not(:empty) leaves glyph-only buttons round. */
html body.ag2:not(#_):not(#__) .menu_button:not(:empty):not(.mes_text *),
html body.ag2:not(#_):not(#__) .menu_button_icon:not(:empty):not(.mes_text *),
html body.ag2:not(#_):not(#__) .api_button {
    white-space: nowrap !important;
    flex-shrink: 0 !important;
    max-width: 100%;
}

html body.ag2:not(#_):not(#__) .extensions_url_block {
    flex: 0 0 auto !important;
}

/* AG Dark §17a · Stable viewport: 小白X's closed quick-launcher is parked below the
   fold; <html> is the fixed containing block (translateZ), so it made the root ~230px
   scrollable and any scrollIntoView() (a click on a control) pushed the whole UI up.
   Layout containment keeps the root exactly one viewport tall. */
html:has(> body.ag2:not(#_):not(#__)) {
    contain: layout;
}

/* == 14 · Accessibility (reduced motion) == */
/* ST adds body.reduced-motion for its own switch AND the OS setting; the media
   query covers the moment before ST has run. Zeroing the duration tokens covers
   every AG2 rule; the catch-all covers ST and third-party CSS. 0.01ms (not 0)
   so transitionend / animationend still fire. */

html body.ag2.reduced-motion:not(#_):not(#__) {
    --ag2-dur-press: 0.01ms;
    --ag2-dur: 0.01ms;
    --ag2-dur-panel: 0.01ms;
}

html body.ag2.reduced-motion:not(#_):not(#__) *,
html body.ag2.reduced-motion:not(#_):not(#__) *::before,
html body.ag2.reduced-motion:not(#_):not(#__) *::after {
    transition-duration: 0.01ms !important;
    transition-delay: 0s !important;
    animation-duration: 0.01ms !important;
    animation-delay: 0s !important;
    animation-iteration-count: 1 !important;
}

@media (prefers-reduced-motion: reduce) {
    html body.ag2:not(#_):not(#__) {
        --ag2-dur-press: 0.01ms;
        --ag2-dur: 0.01ms;
        --ag2-dur-panel: 0.01ms;
    }

    html body.ag2:not(#_):not(#__) *,
    html body.ag2:not(#_):not(#__) *::before,
    html body.ag2:not(#_):not(#__) *::after {
        transition-duration: 0.01ms !important;
        transition-delay: 0s !important;
        animation-duration: 0.01ms !important;
        animation-delay: 0s !important;
        animation-iteration-count: 1 !important;
    }
}
